#include <iostream>
#include <utility>

// Prints a word from each constructor it runs, so each line shows what it cost.
struct Tracer {
  Tracer() = default;
  Tracer(const Tracer&) { std::cout << " copy"; }
  Tracer(Tracer&&) noexcept { std::cout << " move"; }
  Tracer& operator=(const Tracer&) = default;
  Tracer& operator=(Tracer&&) noexcept = default;
  ~Tracer() = default;
};

[[nodiscard]] Tracer make_tracer() { return Tracer{}; }
[[nodiscard]] Tracer pass_through(Tracer t) { return t; }

int main() {
  Tracer a;
  const Tracer frozen;
  std::cout << "1:";
  Tracer b = a;
  std::cout << "\n2:";
  const Tracer c = std::move(a);
  std::cout << "\n3:";
  const Tracer d = make_tracer();
  std::cout << "\n4:";
  const Tracer e = std::move(frozen);
  Tracer&& r = std::move(b);
  std::cout << "\n5:";
  const Tracer f = r;
  std::cout << "\n6:";
  const Tracer g = pass_through(Tracer{});
  std::cout << '\n';
}

