// For a parenthesised expression, decltype gives T& for an lvalue, T&& for an xvalue and T for a prvalue.
template <typename T>
[[nodiscard]] constexpr std::string_view category() {
  if constexpr (std::is_lvalue_reference_v<T>) {
    return "lvalue";
  } else if constexpr (std::is_rvalue_reference_v<T>) {
    return "xvalue";
  } else {
    return "prvalue";
  }
}

struct Reading {
  std::string frame;
};

[[nodiscard]] std::string make_frame() { return "lidar_link"; }

void show(std::string_view expression, std::string_view category) {
  std::cout << std::format("{:<18}{}\n", expression, category);
}

int main() {
  std::string frame = "imu_link";
  std::string&& kept = make_frame();  // the temporary lives as long as the reference
  int count = 0;
  show("frame", category<decltype((frame))>());
  show("kept", category<decltype((kept))>());
  show("\"imu_link\"", category<decltype(("imu_link"))>());
  show("42", category<decltype((42))>());
  show("count + 1", category<decltype((count + 1))>());
  show("++count", category<decltype((++count))>());
  show("count++", category<decltype((count++))>());
  show("make_frame()", category<decltype((make_frame()))>());
  show("std::move(frame)", category<decltype((std::move(frame)))>());
  show("Reading{}.frame", category<decltype((Reading{}.frame))>());
}

#include <iostream>
#include <utility>

// Prints the special member that runs.
struct Tracer {
  Tracer() = default;
  Tracer(const Tracer&) { std::cout << " copy constructor"; }
  Tracer(Tracer&&) noexcept { std::cout << " move constructor"; }
  Tracer& operator=(const Tracer&) {
    std::cout << " copy assignment";
    return *this;
  }
  Tracer& operator=(Tracer&&) noexcept {
    std::cout << " move assignment";
    return *this;
  }
  ~Tracer() = default;
};

void inspect(const Tracer&) { std::cout << " inspect(const Tracer&)"; }
void inspect(Tracer&&) { std::cout << " inspect(Tracer&&)"; }
void keep(Tracer) {}

int main() {
  Tracer t;
  const Tracer frozen;

  std::cout << "a:";
  Tracer&& alias = std::move(t);  // binds a reference to t
  std::cout << "\nb:";
  inspect(std::move(t));  // picks the && overload, which only looks
  std::cout << "\nc:";
  inspect(alias);  // alias has a name, so it is an lvalue
  std::cout << "\nd:";
  keep(std::move(t));  // the parameter is a new object: its move constructor runs
  std::cout << "\ne:";
  keep(std::move(frozen));  // const Tracer&& can't bind to Tracer&&: the copy constructor runs
  std::cout << "\nf:";
  Tracer target;
  target = Tracer{};  // an existing object: move assignment
  std::cout << '\n';
}

