struct Pinned {
  Pinned() = default;
  Pinned(const Pinned&) = delete;
  Pinned& operator=(const Pinned&) = delete;
  Pinned(Pinned&&) = delete;
  Pinned& operator=(Pinned&&) = delete;
  ~Pinned() = default;
};

// Compiles: the prvalue initialises the caller's object directly.
[[nodiscard]] Pinned make_pinned() { return Pinned{}; }

[[nodiscard]] Tracer unnamed() { return Tracer{}; }

[[nodiscard]] Tracer named() {
  Tracer result;
  return result;
}

[[nodiscard]] Tracer parse(std::string_view text) {
  Tracer fallback;
  Tracer parsed;
  if (text.empty()) return fallback;
  return parsed;
}

[[nodiscard]] Tracer from_parameter(Tracer t) { return t; }

#pragma GCC diagnostic push
#pragma GCC diagnostic ignored "-Wpessimizing-move"  // silenced here only to measure what the warning prevents
[[nodiscard]] Tracer moved_out() {
  Tracer result;
  return std::move(result);
}
#pragma GCC diagnostic pop

int main() {
  [[maybe_unused]] const Pinned pinned = make_pinned();
  std::cout << "unnamed:";
  const Tracer a = unnamed();
  std::cout << "\nnamed:";
  const Tracer b = named();
  std::cout << "\nparse:";
  const Tracer c = parse("12.5");
  std::cout << "\nfrom_parameter:";
  const Tracer d = from_parameter(Tracer{});
  std::cout << "\nmoved_out:";
  const Tracer e = moved_out();
  std::cout << '\n';
}

