#include <concepts>
#include <format>
#include <iostream>
#include <string_view>
#include <utility>
#include <vector>

struct Counts {
  int copies = 0;
  int moves = 0;
};

// Counts its copies and moves in a Counts object that outlives it.
class Counted {
 public:
  explicit Counted(Counts& counts) : counts_(&counts) {}
  Counted(const Counted& other) : counts_(other.counts_) { ++counts_->copies; }
  Counted(Counted&& other) noexcept : counts_(other.counts_) { ++counts_->moves; }
  Counted& operator=(const Counted& other) {
    counts_ = other.counts_;
    ++counts_->copies;
    return *this;
  }
  Counted& operator=(Counted&& other) noexcept {
    counts_ = other.counts_;
    ++counts_->moves;
    return *this;
  }
  ~Counted() = default;

 private:
  Counts* counts_;
};

[[nodiscard]] Counted build(Counts& counts) {
  Counted result(counts);
  return result;
}

class Route {
 public:
  explicit Route(Counted leg) : leg_(std::move(leg)) {}  // a sink: by value, then moved into place

 private:
  Counted leg_;
};

// The alternative for comparison: one overload for lvalues and one for rvalues.
class RouteByOverloads {
 public:
  explicit RouteByOverloads(const Counted& leg) : leg_(leg) {}
  explicit RouteByOverloads(Counted&& leg) : leg_(std::move(leg)) {}

 private:
  Counted leg_;
};

void measure(Counts& counts, std::string_view label, std::invocable auto step) {
  const Counts before = counts;
  step();
  std::cout << std::format("{:<32}copies {}, moves {}\n", label, counts.copies - before.copies,
                           counts.moves - before.moves);
}

int main() {
  Counts counts;
  std::vector<Counted> v;
  v.reserve(8);

  measure(counts, "1 push_back(c)", [&] {
    const Counted c(counts);
    v.push_back(c);
  });
  measure(counts, "2 push_back(std::move(c))", [&] {
    Counted c(counts);
    v.push_back(std::move(c));
  });
  measure(counts, "3 push_back(Counted{counts})", [&] { v.push_back(Counted{counts}); });
  measure(counts, "4 emplace_back(counts)", [&] { v.emplace_back(counts); });
  measure(counts, "5 Counted x = build(counts)", [&] { const Counted x = build(counts); });
  measure(counts, "6 x = build(counts)", [&] {
    Counted x(counts);
    x = build(counts);
  });
  measure(counts, "7 Route r(c)", [&] {
    const Counted c(counts);
    const Route r(c);
  });
  measure(counts, "8 Route r(std::move(c))", [&] {
    Counted c(counts);
    const Route r(std::move(c));
  });
  measure(counts, "9 Route r{Counted{counts}}", [&] { const Route r{Counted{counts}}; });
  measure(counts, "10 Counted y = std::move(k)", [&] {
    const Counted k(counts);
    const Counted y = std::move(k);
  });
  measure(counts, "11 overloads r(c)", [&] {
    const Counted c(counts);
    const RouteByOverloads r(c);
  });
  measure(counts, "12 overloads r(std::move(c))", [&] {
    Counted c(counts);
    const RouteByOverloads r(std::move(c));
  });
  measure(counts, "13 overloads r{Counted{counts}}", [&] { const RouteByOverloads r{Counted{counts}}; });
}

