struct Leg {
  std::string name;
  std::int64_t length_mm;
};

// Invariant: total_mm_ is the sum of the legs' lengths.
class Route {
 public:
  void add(Leg leg) {
    legs_.push_back(std::move(leg));
    total_mm_ += legs_.back().length_mm;
  }
  [[nodiscard]] std::ptrdiff_t leg_count() const { return std::ssize(legs_); }
  [[nodiscard]] std::int64_t total_mm() const { return total_mm_; }

 private:
  std::vector<Leg> legs_;
  std::int64_t total_mm_ = 0;
};

int main() {
  Route route;
  route.add({.name = "dock to aisle 3", .length_mm = 4200});
  route.add({.name = "aisle 3 to charger", .length_mm = 2800});
  const Route taken = std::move(route);
  std::cout << std::format("taken: {} legs, {} mm\n", taken.leg_count(), taken.total_mm());
  std::cout << std::format("route: {} legs, {} mm\n", route.leg_count(), route.total_mm());
}

