// Moves through two references; nothing at the call site looks like a self-move.
template <typename T>
void move_into(T& target, T& source) {
  target = std::move(source);
}

int main() {
  std::string frame = "base_link of the mobile robot";
  std::vector<int> ranges_mm{812, 790, 1204};
  move_into(frame, frame);
  move_into(ranges_mm, ranges_mm);
  std::cout << "frame holds " << frame.size() << " chars, ranges_mm " << ranges_mm.size() << " values\n";
}

#include <cstdio>
#include <filesystem>
#include <stdexcept>
#include <utility>
#include <vector>

class File {
 public:
  explicit File(const std::filesystem::path& path) : f_(std::fopen(path.c_str(), "w")) {
    if (f_ == nullptr) throw std::runtime_error("cannot open " + path.string());
  }
  ~File() { close(); }
  File(const File&) = delete;
  File& operator=(const File&) = delete;
  File(File&& other) noexcept : f_(std::exchange(other.f_, nullptr)) {}
  File& operator=(File&& other) noexcept {
    close();
    f_ = std::exchange(other.f_, nullptr);  // when other is *this, f_ gets the closed FILE* back
    return *this;
  }

 private:
  void close() noexcept {
    if (f_ != nullptr) std::fclose(f_);
  }
  std::FILE* f_;
};

// Replaces the oldest log with the newest. With one log, both are the same object.
void rotate(std::vector<File>& logs) { logs.front() = std::move(logs.back()); }

int main() {
  std::vector<File> logs;
  logs.emplace_back("run.log");
  rotate(logs);
}

File& operator=(File&& other) noexcept {
  std::FILE* incoming = std::exchange(other.f_, nullptr);
  close();  // on a self-move, f_ is already nullptr here, so nothing is closed
  f_ = incoming;
  return *this;
}

#include <cstdint>
#include <format>
#include <iostream>
#include <string>
#include <string_view>
#include <type_traits>
#include <utility>
#include <vector>

struct Leg {
  std::string name;
  std::int64_t length_mm;
};

// Invariant: total_mm_ is the sum of the legs' lengths, in every state, moved-from included.
class Route {
 public:
  Route() = default;
  Route(const Route&) = default;
  Route& operator=(const Route&) = default;
  Route(Route&& other) noexcept
      : legs_(std::exchange(other.legs_, {})), total_mm_(std::exchange(other.total_mm_, 0)) {}
  Route& operator=(Route&& other) noexcept {
    Route taken(std::move(other));  // empties other, even when other is *this
    swap(taken);                    // *this gets the value, and taken leaves with the old one
    return *this;
  }
  ~Route() = default;

  void swap(Route& other) noexcept {
    legs_.swap(other.legs_);
    std::swap(total_mm_, other.total_mm_);
  }
  void add(Leg leg) {
    legs_.push_back(std::move(leg));
    total_mm_ += legs_.back().length_mm;
  }
  [[nodiscard]] std::string describe() const {
    return std::format("{} mm in {} {}", total_mm_, legs_.size(), legs_.size() == 1 ? "leg" : "legs");
  }

 private:
  std::vector<Leg> legs_;
  std::int64_t total_mm_ = 0;
};

static_assert(std::is_nothrow_move_constructible_v<Route> && std::is_nothrow_move_assignable_v<Route>);

// Moves through two references, the way an algorithm or a container does.
void move_into(Route& target, Route& source) { target = std::move(source); }

void show(std::string_view label, const Route& route) { std::cout << std::format("{:<19}{}\n", label, route.describe()); }

int main() {
  Route route;
  route.add({.name = "dock to aisle 3", .length_mm = 4200});
  route.add({.name = "aisle 3 to charger", .length_mm = 2800});

  Route taken = std::move(route);
  show("taken:", taken);
  show("route, moved from:", route);

  route.add({.name = "charger to dock", .length_mm = 1500});
  show("route, reused:", route);

  move_into(taken, taken);
  show("taken, self-move:", taken);

  const Route copy = taken;
  show("copy of taken:", copy);
}
